def find_golomb(n, current_marks, used_diffs, max_len):
    if len(current_marks) == n:
        return current_marks

    last_mark = current_marks[-1]
    # Try next mark
    for next_mark in range(last_mark + 1, max_len + 1):
        new_diffs = []
        possible = True
        for m in current_marks:
            diff = next_mark - m
            if diff in used_diffs:
                possible = False
                break
            new_diffs.append(diff)

        if possible:
            result = find_golomb(n, current_marks + [next_mark], used_diffs.union(new_diffs), max_len)
            if result:
                return result
    return None

